solution.code:
const original = { name: 'Ada', settings: { theme: 'light' } };
const copy = { ...original }; // shallow copy of top-level keys
copy.name = 'Grace';

console.log(original.name); // 'Ada' — unchanged
console.log(copy.name); // 'Grace'

function keyById(items) {
  return items.reduce((acc, item) => {
    acc[item.id] = item;
    return acc;
  }, {});
}

const users = [{ id: 1, name: 'Ada' }, { id: 2, name: 'Grace' }];
console.log(keyById(users));
// { '1': { id: 1, name: 'Ada' }, '2': { id: 2, name: 'Grace' } }
